result.args:
位置参数数组：[filter?: {
    /** 可选子树根的节点身份；查询包含根节点本身及全部后代，省略时查整个目标。 */
    subtree?: NodeHandle;
    /** 可选名称筛选；equals 与 contains 同时提供时都必须满足，节点名称允许重复。 */
    name?: {
        /** 要求保存名称完全相等的字符串；与 contains 同时提供时按 AND 合并，不保证唯一匹配。 */
        equals?: string;
        /** 要求保存名称包含的子串；使用当前实现的区分大小写匹配，与 equals 同时提供时都需满足。 */
        contains?: string;
    };
    /** 可选组件字段键；只返回实际存在该组件的节点，字段名称从 components.listTypes 取得。 */
    hasComponent?: string;
    /** 可选自身活动开关筛选；省略时不按活动配置过滤，不表示运行中的层级有效活动状态。 */
    active?: boolean;
    /** 可选的精确层级深度；相对于整个场景根，根为 0，不是相对于 subtree 根的偏移。 */
    depth?: number;
}, options?: {
    /** 请求的最大条数，必须为正安全整数，默认 100；不设置固定条数或单页字节数上限。 */
    limit?: number;
    /** 上一页的 nextCursor，原样传回；继续分页时保留同一目标、筛选和投影，编辑或查询变化后须从头读取。 */
    cursor?: string;
    /** 可选返回字段键；省略使用方法默认投影，空数组表示不取行字段。是否支持行投影以方法签名为准。 */
    fields?: ("handle" | "name" | "parent" | "active" | "layer" | "tag" | "depth" | "componentTypes" | "interactionPoint" | "previewNodeId")[];
}]
args[0] filter: 可选节点筛选，各条件同时满足；省略查询整个目标，不能用名称假定唯一节点。
args[1] options: 可选分页与行字段投影；limit 默认为 100，须为正安全整数，无固定上限，继续 cursor 时保持筛选与字段不变。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

result.returns:
{
    /** 本页实际返回的记录，字段范围以请求投影为准；即使不足 limit，也应检查 nextCursor 是否仍有后续。 */
    items: Partial<{
        /** 当前文档中的节点句柄；WPrefab 使用 n<node.id>，ID 复用后定位新节点，不按显示名查找。 */
        handle: NodeHandle;
        /** 保存的节点显示名；允许重名，定位时结合 parent/subtree 等条件，不把名称当唯一身份。 */
        name: string;
        /** 父节点身份；场景根节点为 null。改变父级请使用 nodes.reparent，不直接修改此返回值。 */
        parent: NodeHandle | null;
        /** 节点保存的 isActive 开关；表示节点自身的活动配置，不是包含所有祖先影响后的最终运行状态。 */
        active: boolean;
        /** Unity Layer 编号，范围 0..31；不是 Layer 显示名称。 */
        layer: number;
        /** Unity Tag 字符串；新建节点默认为 Untagged，最终可用 Tag 受当前 Runtime 配置约束。 */
        tag: string;
        /** 从场景根开始的层级深度；根节点为 0，父子层级每深入一级加 1。 */
        depth: number;
        /** 节点实际存在的组件字段键列表，例如 physicsColliderData；不包含完整组件值，详情使用 components.get。 */
        componentTypes: string[];
        /** 纯锚点的触控用途标记；无标记时为 null，存在标记不代表已经生成拾取/乘坐玩法脚本。 */
        interactionPoint: {
            /** 触控用途：PickUp 表示拾取锚点，Seat 表示座位锚点；它是编辑元数据，不会自动创建 Trigger 或脚本。 */
            kind: "PickUp" | "Seat";
        } | null;
        /** 宿主预览使用的 Runtime 数字节点 ID，只读；外层工具需要数字 ID 时可使用，SDK 编辑仍要求 handle。 */
        previewNodeId: number;
    }>[];
    /** 是否仍有未返回的记录；为 true 时使用 nextCursor 继续读取，不表示场景或源码被截断保存。 */
    truncated: boolean;
    /** 存在后续记录时返回的游标；缺省表示已读完，不能解析、拼接或跨查询复用。 */
    nextCursor?: string;
}
节点分页结果；省略 fields 时只返回 handle/name/componentTypes，其余字段需显式请求，有 nextCursor 时继续分页。
默认与运行时可变投影均返回部分节点，读取字段前确认其存在。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。
